import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
from typing import Sequence, Dict, Any

def _define_hyperparameters():
    return {
        'learning_rate': 0.001, 'd_model': 256, 'num_blocks_per_path': 2,
        'kernel_size': 7, 'dropout_rate': 0.1, 'tau': 0.25
    }

# --- Shared Components ---
class DSConvDilatedBlock(nn.Module):
    d_model: int; kernel_size: int = 7; dilation: int = 1; dropout_rate: float = 0.1
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.LayerNorm()(x)
        h = nn.Conv(features=self.d_model, kernel_size=(self.kernel_size,), feature_group_count=self.d_model, padding='SAME', kernel_dilation=(self.dilation,))(h)
        h = nn.gelu(h); h = nn.Conv(features=self.d_model, kernel_size=(1,))(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        return x + h

class DSConvPath(nn.Module):
    d_model: int; num_blocks: int; dilations: Sequence[int]; kernel_size: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = x
        for i in range(self.num_blocks):
            d = self.dilations[i % len(self.dilations)]
            h = DSConvDilatedBlock(self.d_model, self.kernel_size, d, self.dropout_rate)(h, deterministic=deterministic)
        return h

def lse_pool(h: jnp.ndarray, tau: float):
    x = h / tau; m = jnp.max(x, axis=1, keepdims=True)
    return tau * (jnp.log(jnp.mean(jnp.exp(x - m), axis=1) + 1e-12) + jnp.squeeze(m, axis=1))

# --- Main Network: Multi-Path DSConv Feature Extractor ---
class MultiPathDSConvNet(nn.Module):
    d_output: int; task_type: str; d_model: int; num_blocks_per_path: int; 
    kernel_size: int; dropout_rate: float; tau: float

    @nn.compact
    def __call__(self, x, deterministic=True):
        # Initial projection
        h = nn.Dense(self.d_model)(x); h = nn.gelu(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)

        # Define parallel paths with different dilation schedules
        path1 = DSConvPath(self.d_model, self.num_blocks_per_path, [1, 2, 4, 8], self.kernel_size, self.dropout_rate)(h, deterministic)
        path2 = DSConvPath(self.d_model, self.num_blocks_per_path, [1, 3, 9, 27], self.kernel_size, self.dropout_rate)(h, deterministic)
        path3 = DSConvPath(self.d_model, self.num_blocks_per_path, [1, 1, 2, 2], self.kernel_size, self.dropout_rate)(h, deterministic)

        # Concatenate path outputs
        concatenated_features = jnp.concatenate([path1, path2, path3], axis=-1)

        # Project back to d_model
        features_seq = nn.Dense(self.d_model)(concatenated_features)

        # Use a simple, proven aggregator (Noema's Mean+Max) for a clean test of the backbone
        mean_vec = jnp.mean(features_seq, axis=1)
        max_vec = jnp.max(features_seq, axis=1)
        fused = jnp.concatenate([mean_vec, max_vec], axis=-1)

        z = nn.LayerNorm()(fused)
        z = nn.Dense(self.d_model)(z); z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        logits = nn.Dense(self.d_output)(z)
        return logits.squeeze(-1) if self.task_type == 'regression' and self.d_output == 1 else logits

class NetworkWrapper:
    def __init__(self, model_instance): self.network = model_instance
    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key); return self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
    def apply(self, params, x, deterministic=True, rng_key=None):
        if rng_key is None: rng_key = random.PRNGKey(0); return self.network.apply(params, x, deterministic=deterministic, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    model = MultiPathDSConvNet(**{k: v for k, v in hparams.items() if k in MultiPathDSConvNet.__annotations__}); return NetworkWrapper(model)
